import {
  useQuery,
} from "@tanstack/react-query";

import weatherService from "../service/weather.service";

import {
  WeatherSummaryData,
  WeatherOutlookDay,
  WeatherSignalsData,
} from "../types/weather.types";


export const useWeatherSummary = (
  entityId: string
) => {
  return useQuery<
    WeatherSummaryData | null
  >({
    queryKey: [
      "weather-summary",
      entityId,
    ],

    queryFn: () =>
      weatherService.getWeatherSummary(
        entityId
      ),

    enabled:
      Boolean(entityId),

    staleTime:
      5 * 60 * 1000,

    refetchOnWindowFocus:
      false,
  });
};


export const useWeatherOutlook = (
  entityId: string,
  days: number
) => {
  return useQuery<
    WeatherOutlookDay[]
  >({
    queryKey: [
      "weather-outlook",
      entityId,
      days,
    ],

    queryFn: () =>
      weatherService.getWeatherOutlook(
        entityId,
        days
      ),

    enabled:
      Boolean(entityId),

    staleTime:
      5 * 60 * 1000,

    refetchOnWindowFocus:
      false,
  });
};


export const useWeatherSignals = (
  entityId: string,
  days: number
) => {
  return useQuery<
    WeatherSignalsData
  >({
    queryKey: [
      "weather-signals",
      entityId,
      days,
    ],

    queryFn: () =>
      weatherService.getWeatherSignals(
        entityId,
        days
      ),

    enabled:
      Boolean(entityId),

    staleTime:
      5 * 60 * 1000,

    refetchOnWindowFocus:
      false,
  });
};
